async function drawNecklace(){
 const r=result,n=r.n,j=r.column,edge=r.classes[j],s=edge?r.permutation_rows[edge[0]-1]:null,t=edge?r.permutation_rows[edge[1]-1]:null;
 const vals=[r.M,r.M,r.D_M,r.P_D_M][necklaceStep].map(row=>row[j]);
 let out='<svg viewBox="0 0 460 410" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Half-open cyclic interval and its endpoint jumps"><circle cx="230" cy="200" r="140" fill="none" stroke="#d1dfe5"/>';
 for(let i=0;i<n;i++){
  const ang=i*2*PI/n-PI/2,x=230+140*Math.cos(ang),y=200+140*Math.sin(ang),active=vals[i]!==0,color=vals[i]<0?C.red:C.teal;
  if(necklaceStep<=1&&r.original_M[i][j]===-1){const prev=ang-PI/n,next=ang+PI/n;out+=`<path d="M${230+140*Math.cos(prev)} ${200+140*Math.sin(prev)} A140 140 0 0 1 ${230+140*Math.cos(next)} ${200+140*Math.sin(next)}" stroke="${C.teal}" stroke-width="7" fill="none" opacity=".32"/>`;}
  out+=`<circle cx="${x}" cy="${y}" r="${active?17:12}" fill="${active?color:'white'}" stroke="${active?color:'#aac0ca'}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12" fill="${active?'white':C.ink}">${active?(vals[i]>0?'+':'')+vals[i]:'0'}</text><text x="${230+174*Math.cos(ang)}" y="${200+174*Math.sin(ang)+5}" text-anchor="middle" font-size="13" fill="${C.ink}">${necklaceStep===3?'label':'row'} ${i+1}</text>`;
 }
 out+=`<text x="230" y="193" text-anchor="middle" font-size="19" fill="${C.ink}">${edge?edge.join(' → '):r.pairs[j].join(', ')}</text><text x="230" y="218" text-anchor="middle" font-size="12" fill="${C.muted}">${['half-open arc','exponent m','cyclic Dm','relabeled P Dm'][necklaceStep]}</text></svg>`;
 $('necklace-circle').innerHTML=out;
 $('arc-formula').innerHTML=edge?`<div class="formula">m<sub>r</sub> = −1<sub>r∈(${s},${t}]</sub><br>P<sub>f</sub>D m = e<sub>${edge[1]}</sub> − e<sub>${edge[0]}</sub></div><p>The open end is s<sub>${edge[0]}</sub> = ${s}; the closed end is s<sub>${edge[1]}</sub> = ${t}.</p>`:'<div class="formula">Noncrossing pair: m = 0, &nbsp; B column = 0.</div>';
 const z=Array.from({length:n},(_,i)=>[r.original_M[i][j],r.M[i][j],r.D_M[i][j],r.P_D_M[i][j]]);
 await plot('necklace-strip',[{type:'heatmap',z,x:['reference m','current m','D m','P D m'],y:Array.from({length:n},(_,i)=>i+1),zmin:-2,zmax:2,colorscale:[[0,'#ae3448'],[.5,'#f6f9fa'],[1,'#16766c']],showscale:false,text:z,texttemplate:'%{text}',textfont:{size:15},xgap:4,ygap:4,hovertemplate:'%{x}<br>row %{y}: %{z}<extra></extra>'}],{margin:{l:38,r:18,t:25,b:45},xaxis:{side:'bottom'},yaxis:{autorange:'reversed',title:'row / relabeled vertex',dtick:1},shapes:[{type:'rect',xref:'x',yref:'paper',x0:Math.max(0,necklaceStep)-.48,x1:Math.max(0,necklaceStep)+.48,y0:0,y1:1,line:{color:C.gold,width:2}}]});
 $('necklace-metrics').innerHTML=metricHTML([['Maximum integer error',String(r.error)],['Status',r.error?'Control rejected':'Identity agrees'],['Crossing orientation',edge?edge.join('→'):'none']]);
 await plot('necklace-error',[{type:'heatmap',z:r.difference,x:r.pairs.map(p=>p.join(',')),y:Array.from({length:n},(_,i)=>i+1),zmin:-1,zmax:1,colorscale:[[0,'#ae3448'],[.5,'#eff5f3'],[1,'#16766c']],showscale:false,text:r.difference,texttemplate:n<=5?'%{text}':'',xgap:2,ygap:2,hovertemplate:'Pair %{x}<br>label %{y}<br>integer discrepancy %{z}<extra></extra>'}],{margin:{l:40,r:15,t:20,b:48},xaxis:{tickangle:-45,title:'unordered pair columns'},yaxis:{autorange:'reversed',dtick:1,title:'label'}});
 $('necklace-data').innerHTML='<p>Necklace: '+r.necklace.map((I,i)=>`I${i+1}={${I.join(',')}}`).join(' · ')+'</p><h3>M<sub>N</sub></h3>'+matrixTable(r.M,0)+'<h3>P D M<sub>N</sub></h3>'+matrixTable(r.P_D_M,0)+'<h3>B</h3>'+matrixTable(r.B,0);
}
function currentView(){return {cycleKeep,broken:!!$('broken')?.checked,volumeSelected,explode:Number($('explode')?.value||0),necklaceStep,iteration:Number($('iteration')?.value||0),dense:view.dense?{eta:view.dense.eta,bary:view.dense.bary}:null};}
async function restoreView(v){
 if(!v||typeof v!=='object')return;
 if(lab==='cycles'){
  if(Array.isArray(v.cycleKeep)&&v.cycleKeep.length===result.cycles.length&&v.cycleKeep.every(x=>typeof x==='boolean'))cycleKeep=v.cycleKeep;
  if(typeof v.broken==='boolean')$('broken').checked=v.broken;
  await render();
  if(v.dense&&live){try{view.dense=await compute({action:'dense',...v.dense});await drawDense();}catch(e){fail(e.message);}}
 }
 if(lab==='volume'){
  if(Number.isInteger(v.volumeSelected)&&v.volumeSelected>=-1&&v.volumeSelected<result.fans.length)volumeSelected=v.volumeSelected;
  if(Number.isFinite(v.explode)&&v.explode>=0&&v.explode<=1)setVal('explode',v.explode);
  await drawVolume();
 }
 if(lab==='necklace'&&Number.isInteger(v.necklaceStep)&&v.necklaceStep>=0&&v.necklaceStep<=3){necklaceStep=v.necklaceStep;setVal('stage',necklaceStep);await drawNecklace();}
 if(lab==='landscape'&&Number.isInteger(v.iteration))await drawInverse(v.iteration);
}
$('restart').addEventListener('click',boot);
$('share').addEventListener('click',async()=>{const u=new URL(location.href);u.hash=encodeState({lab,request:state,view:currentView()});try{await navigator.clipboard.writeText(u.href);$('share').textContent='Copied';setTimeout(()=>$('share').textContent='Copy state link',1500);}catch{history.replaceState(null,'',u.href);status('State URL updated in the address bar. Copy it from there.');}});
$('export').addEventListener('click',()=>download('clh-'+lab+'-state.json',JSON.stringify({schema:'lrl.clh-lab/v1',lab,request:state,result,view:{...currentView(),denseResult:view.dense||null},runtime:window.__CLH_NATIVE__?'native-test':window.__CLH_RUNTIME__||'recorded snapshot',scope:'Numerical experiment, not a proof certificate.'},null,2)));
async function main(){
 try{
 [starters,triangleMesh,shiftMesh]=await Promise.all([loadJSON('data/starters.json'),loadJSON('data/triangle-mesh.json'),loadJSON('data/shift-mesh.json')]);setup();
 $('presets').innerHTML=starters[lab].map((p,i)=>`<button data-preset="${i}">${esc(p.title)}</button>`).join('');
 document.querySelectorAll('[data-preset]').forEach(e=>e.addEventListener('click',async()=>{++revision;clearTimeout(debounceTimer);clearError();const p=starters[lab][+e.dataset.preset];state=structuredClone(p.request);result=structuredClone(p.result);cycleKeep=[];await render();status(live?(window.__CLH_NATIVE__?'Native CPython test transport · displayed a recorded example':'Browser Python ready · displayed a recorded example'):'Recorded numerical example · custom calculation awaits browser Python',live?'ready':'');}));
 const p=starters[lab][0];state=structuredClone(p.request);result=structuredClone(p.result);await render();window.__CLH_APP_READY__=true;await boot();
 if(location.hash && !["g01","gauge","observable","scope-import","scope-local","g02","cycle-proof","integral"].includes(location.hash.slice(1)) && !/^g03(-[a-z]+)?$/.test(location.hash.slice(1))){try{const saved=decodeState(location.hash.slice(1));if(saved.lab===lab&&saved.request?.action===lab){if(window.__CLH_NATIVE__){await update(saved.request);await restoreView(saved.view);}else{const handle=setInterval(()=>{if(live){clearInterval(handle);update(saved.request).then(()=>restoreView(saved.view));}},250);setTimeout(()=>clearInterval(handle),91000);}}}catch(e){fail('Invalid shared state: '+e.message);}}
 }catch(e){fail(e.message);status('Could not load the local assets. Serve the complete folder over HTTP.','failed');}
}
main();

